function textW(s, sc){ return s.length*6*sc - sc; }
function drawText(str, x, y, color, sc, center){
  sc = sc || 1;
  if(center) x = Math.round(x - textW(str, sc)/2);
  ctx.fillStyle = color;
  let cx = x;
  for(const ch of str){
    const gl = FONT[ch] || FONT[' '];
    for(let r=0;r<7;r++) for(let c=0;c<5;c++)
      if(gl[r][c]==='1') ctx.fillRect(cx+c*sc, y+r*sc, sc, sc);
    cx += 6*sc;
  }
}

// ---------------- Web Audio (synthesized) ----------------
let AC = null, muted = false, noiseBuf = null;
function initAudio(){
  if(AC){ if(AC.state==='suspended') AC.resume(); return; }
  try{ AC = new (window.AudioContext || window.webkitAudioContext)(); }catch(e){ AC = null; }
}
function tone(f0, f1, dur, type, vol, delay){
  if(!AC || muted) return;
  delay = delay || 0;
  const t = AC.currentTime + delay;
  const o = AC.createOscillator(), g = AC.createGain();
  o.type = type; o.frequency.setValueAtTime(f0, t);
  if(f1 !== f0) o.frequency.exponentialRampToValueAtTime(Math.max(1,f1), t+dur);
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t+dur);
  o.connect(g); g.connect(AC.destination);
  o.start(t); o.stop(t+dur+0.03);
}
function noiseBurst(dur, vol, freq, delay){
  if(!AC || muted) return;
  delay = delay || 0;
  if(!noiseBuf){
    noiseBuf = AC.createBuffer(1, AC.sampleRate, AC.sampleRate);
    const d = noiseBuf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i] = Math.random()*2-1;
  }
  const t = AC.currentTime + delay;
  const s = AC.createBufferSource(); s.buffer = noiseBuf;
  const f = AC.createBiquadFilter(); f.type='lowpass'; f.frequency.value = freq;
  const g = AC.createGain();
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t+dur);
  s.connect(f); f.connect(g); g.connect(AC.destination);
  s.start(t); s.stop(t+dur);
}
const SFX = {
  shot:       () => tone(900, 200, 0.12, 'square', 0.10),
  enemyHit:   () => tone(320, 110, 0.08, 'square', 0.14),
  enemyBoom:  () => { noiseBurst(0.22, 0.18, 1400); tone(420, 60, 0.18, 'sawtooth', 0.08); },
  bossHit:    () => tone(210, 80, 0.14, 'square', 0.18),
  bossBoom:   () => { noiseBurst(0.4, 0.26, 900); tone(300, 40, 0.35, 'sawtooth', 0.14); },
  playerBoom: () => { noiseBurst(0.5, 0.3, 700); tone(500, 30, 0.5, 'sawtooth', 0.18); },
  beam:       (dur) => {
    if(!AC || muted) return;
    const t = AC.currentTime;
    const o = AC.createOscillator(), g = AC.createGain();
    const l = AC.createOscillator(), lg = AC.createGain();
    o.type='sawtooth'; o.frequency.value = 150;
    l.type='sine'; l.frequency.value = 13; lg.gain.value = 55;
    l.connect(lg); lg.connect(o.frequency);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.10, t+0.12);
    g.gain.setValueAtTime(0.10, Math.max(t+0.13, t+dur-0.1));
    g.gain.linearRampToValueAtTime(0.0001, t+dur);
    o.connect(g); g.connect(AC.destination);
    o.start(t); l.start(t); o.stop(t+dur); l.stop(t+dur);
  },
  jingle:     () => [660,880,990,1320].forEach((f,i)=> tone(f, f, 0.09, 'square', 0.10, i*0.09)),
  extra:      () => [523,659,784,1046].forEach((f,i)=> tone(f, f, 0.1, 'square', 0.10, i*0.08)),
