// ---------------- high score persistence ----------------
function loadHigh(){ try{ return parseInt(localStorage.getItem('galagaHighScore')) || 0; }catch(e){ return 0; } }
function saveHigh(){ try{ localStorage.setItem('galagaHighScore', String(highScore)); }catch(e){} }
let highScore = loadHigh();

// ---------------- game state ----------------
const STEP = 1/60;
