const player = {
  x:112, y:272, mode:'ready', t:0,
  dual:false, redSide:'R', fireCd:0,
  capX:112, capY:272, capT:0
};

let enemies = [], shots = [], ebullets = [], booms = [], popups = [], freed = [];
