let stars = [];

function isChall(s){ return s >= 3 && (s-3) % 4 === 0; }
function stageDenom(s){ return [1,5,10,20,30,50][(s-1) % 6]; }
const FLAG_COLORS = {1:'#3399ff',5:'#ff3333',10:'#ffee00',20:'#33cc33',30:'#ff8800',50:'#9933ff'};

// ---------------- starfield ----------------
(function(){
  const cols = ['#ffffff','#88aaff','#ffdd66','#66ffff'];
  for(let i=0;i<42;i++){
    const big = Math.random() < 0.25;
    stars.push({ x:(Math.random()*W)|0, y:(Math.random()*H)|0,
      c: cols[(Math.random()*4)|0], sp: big ? 26 : 12,
      ph: Math.random()*6.28, tw: 2 + Math.random()*4, big });
  }
})();
function updateStars(dt){
  for(const s of stars){
    s.y += s.sp*dt;
    if(s.y >= H){ s.y -= H; s.x = (Math.random()*W)|0; }
  }
}
function drawStars(){
  for(const s of stars){
    const a = 0.45 + 0.55*Math.sin(time*s.tw + s.ph);   // twinkle
    if(a < 0.15) continue;
    ctx.globalAlpha = a;
    ctx.fillStyle = s.c;
    ctx.fillRect(s.x, s.y, s.big ? 2 : 1, s.big ? 2 : 1);
  }
  ctx.globalAlpha = 1;
}

// ---------------- helpers ----------------
function clamp(v,a,b){ return v<a?a : v>b?b : v; }
function rand(a,b){ return a + Math.random()*(b-a); }
function bez(p, t){
  const u = 1-t;
  return {
    x: u*u*u*p[0].x + 3*u*u*t*p[1].x + 3*u*t*t*p[2].x + t*t*t*p[3].x,
    y: u*u*u*p[0].y + 3*u*u*t*p[1].y + 3*u*t*t*p[2].y + t*t*t*p[3].y
  };
}
function aabb(ax,ay,aw,ah, bx,by,bw,bh){
  return ax < bx+bw && bx < ax+aw && ay < by+bh && by < ay+ah;
}
function addPopup(x, y, txt, color){ popups.push({x: clamp(x,16,208), y, txt, color: color||'#fff', t:0}); }
function addBoom(x, y, set, step){ booms.push({x, y, f:0, step: step||0.055, set}); }

// ---------------- scoring / ships ----------------
function addScore(n){
  score += n;
  if(score > highScore) highScore = score;
  while(score >= nextExtra){
    if(reserve < 9) reserve++;
    SFX.extra();
    addPopup(112, 200, 'EXTRA SHIP', '#33ccff');
    nextExtra += 70000;
  }
}

// ---------------- formation slots ----------------
let SLOTS = [];
function buildSlots(){
  SLOTS = [];
  for(let i=0;i<4;i++)  SLOTS.push({x:64+i*32, y:48,  type:'boss'});
  for(let r=0;r<2;r++) for(let i=0;i<8;i++) SLOTS.push({x:28+i*24, y:80+r*24, type:'goye'});
  for(let r=0;r<2;r++) for(let i=0;i<10;i++) SLOTS.push({x:22+i*20, y:128+r*24, type:'zako'});
}
function entryPath(slot, side){
  if(side < 0) return [{x:-32,y:36},{x:24,y:236},{x:112,y:236},{x:slot.x,y:slot.y}];
  return [{x:256,y:36},{x:200,y:236},{x:112,y:236},{x:slot.x,y:slot.y}];
}
function makeEnemy(slot, side, delay, pathDur, opts){
  opts = opts || {};
  return {
    type: slot.type, slot, side,
    st: 'wait', t: -delay,
    path: entryPath(slot, side), dur: pathDur,
    x: side<0 ? -32 : 256, y: 36,
    hp: slot.type==='boss' ? 2 : 1,
    captive: false,
    esc: opts.esc || 0,
    fireAt: opts.fireAt || [],
    animFrame: 0, animT: 0,
    dead: false
  };
}

// ---------------- stage setup ----------------
function setupStage(){
  buildSlots();
  enemies = []; shots = []; ebullets = []; booms = []; popups = []; freed = [];
  entryQ = []; diveT = 0; formFireT = 0; formT = 0;
  formationFull = false; stageClear = false; clearT = 0; beam = null;
  stageTime = 0;
  const d = Math.max(1.5, 2.3 - stage*0.06);
  if(isChall(stage)){
    chall = { waves: [], waveT: 2.5, done: false };
    for(let w=0; w<5; w++){
      const dir = w % 2 ? -1 : 1;
      const wave = { dir, x0: dir>0 ? 8 : 216, kills:0, spawned:0, done:false, bonus:false, enemies:[] };
      const n = [0,0,0,0,0].indexOf(w);
      for(let j=0;j<8;j++){
        const type = j<4 ? 'zako' : (j<6 ? 'goye' : 'boss');
        wave.enemies.push({ type, j, dir, x0: wave.x0 });
      }
      chall.waves.push(wave);
    }
  } else {
    chall = null;
    const groups = [
      {type:'boss', side:-1, t:0.6},
      {type:'goye', side: 1, t:1.9, rows:[0]},
      {type:'goye', side:-1, t:3.2, rows:[1]},
      {type:'zako', side: 1, t:4.5, rows:[0]},
      {type:'zako', side:-1, t:5.8, rows:[1]}
    ];
    for(const g of groups){
      const slots = SLOTS.filter(s => s.type===g.type && (!g.rows || g.rows.indexOf(
        SLOTS.indexOf(s) - (g.type==='boss'?0 : g.type==='goye'?4 : 20)) >= 0));
      let k = 0;
      for(const s of slots){
        const isRow = g.type==='goye' ? (s.y===80 ? 0 : 1) : (s.y===128 ? 0 : 1);
        if(g.rows && g.rows.indexOf(isRow) < 0) continue;
        entryQ.push({ t: g.t + k*0.13, slot: s, side: g.side, dur: d,
          fireAt: Math.random()<0.5 ? [rand(0.4,0.8)] : [] });
        k++;
      }
    }
  }
}

// ---------------- diving ----------------
function divePath(x, y){
  const px = clamp(player.x, 20, 204);
  const j = () => rand(-14, 14);
  return { path: [{x, y},{x:px+j(), y:185},{x:px+j(), y:262},{x:px+j()*1.5, y:330}], dur: 1.5 };
}
function returnPath(e){
  const sx = e.slot.x, sy = e.slot.y;
  const tx = clamp(sx + rand(-30,30), 16, 208);
  return { path: [{x:tx, y:-20},{x:tx, y:60},{x:sx, y:sy+40},{x:sx, y:sy}], dur: 1.1 };
}
function pickDiver(){
  const inForm = enemies.filter(e => e.st==='formation' && !e.captive);
  if(!inForm.length) return null;
  const roll = Math.random();
  let pool;
  if(roll < 0.55) pool = inForm.filter(e => e.type==='zako');
  else if(roll < 0.8) pool = inForm.filter(e => e.type==='goye');
  else pool = inForm.filter(e => e.type==='boss' && !e.captive);
  if(!pool.length) pool = inForm;
  return pool[(Math.random()*pool.length)|0];
}
function startDive(){
  const e = pickDiver();
  if(!e) return;
  if(e.type === 'boss'){
    const withCaptive = e.captive;
    const nEsc = withCaptive ? 0 : (stage>=2 ? (Math.random()<0.6 ? (Math.random()<0.5?2:1) : 1) : (Math.random()<0.35?1:0));
    const escs = [];
    if(nEsc > 0){
      const goyes = enemies.filter(o => o!==e && o.st==='formation' && o.type==='goye' && !o.captive);
      for(let i=0;i<nEsc && goyes.length;i++) escs.push(goyes.splice((Math.random()*goyes.length)|0,1)[0]);
    }
    e.st='diving'; e.t=0; e.esc = escs.length;
    const p = divePath(e.x, e.y);
    e.path = p.path; e.dur = 1.7;
    e.fireAt = withCaptive ? [] : [0.45, 0.85].filter(()=>Math.random()<0.8);
    if(escs.length === 2){ e.path[1].x += 0; }
    escs.forEach((o,i) => {
      o.st='diving'; o.t=0; o.esc=0;
      const off = i===0 ? -16 : 16;
      o.path = e.path.map(pt => ({x: pt.x+off, y: pt.y}));
      o.dur = e.dur;
      o.fireAt = Math.random()<0.6 ? [0.6] : [];
    });
  } else {
    e.st='diving'; e.t=0; e.esc=0;
    const p = divePath(e.x, e.y);
    e.path = p.path; e.dur = p.dur;
    e.fireAt = Math.random()<0.7 ? [rand(0.3,0.7)] : [];
  }
}
function startCaptiveDive(boss){
  boss.st='diving'; boss.t=0; boss.esc=0;
  const px = clamp(player.x, 30, 194);
  boss.path = [{x:boss.x, y:boss.y},{x:px, y:120},{x:px, y:168},{x:px, y:176}];
  boss.dur = 1.4;
  boss.fireAt = [];
}

// ---------------- enemy bullets ----------------
function eFire(x, y, aimPlayer){
  if(ebullets.length >= 9) return;
  let dx = 0, dy = 1;
  if(aimPlayer){
    dx = player.x - x; dy = player.y - y;
    const d = Math.hypot(dx,dy) || 1; dx/=d; dy/=d;
  }
  const sp = Math.min(150, 75 + stage*7);
  ebullets.push({ x, y, vx: dx*sp, vy: Math.max(dy*sp, 40) });
}

// ---------------- player ----------------
function killPlayer(){
  if(player.mode !== 'play') return;
  player.mode = 'dead'; player.t = 0; player.dual = false;
  addBoom(player.x, player.y, BOOM_P, 0.07);
  SFX.playerBoom();
  if(reserve > 0){ reserve--; respawnT = 1.4; }
  else { overT = 1.2; }   // switch to game over shortly
}
let respawnT = 0;
function respawn(){
  player.x = 112; player.mode = 'ready'; player.t = 0; player.dual = false;
  SFX.jingle();
}
function updatePlayer(dt){
  player.fireCd = Math.max(0, player.fireCd - dt);
  if(overT > 0){ overT -= dt; if(overT <= 0){ state='over'; overT=0; saveHigh(); } return; }

  if(player.mode === 'ready'){
    player.t += dt;
    if(player.t > 1.1){ player.mode='play'; player.t=0; }
    return;
  }
  if(player.mode === 'dead'){
    player.t += dt;
    if(respawnT > 0){
      respawnT -= dt;
      if(respawnT <= 0 && player.t > 0.5) respawn();
    }
    return;
  }
  if(player.mode === 'captured'){
    // ship is pulled up along the beam toward the boss
    player.capT += dt;
    const k = Math.min(1, player.capT / 0.7);
    player.capX = player.x;
    player.capY = player.y + (player.capTargetY - player.y) * k;
    if(k >= 1){
      // attach as captive to the boss, lose this ship
      const boss = beam ? beam.boss : null;
      if(boss && !boss.dead) boss.captive = true;
      player.mode = 'gone';
      if(reserve > 0){ reserve--; respawnT = 1.2; }
      else { overT = 0.8; }
    }
    return;
  }
  if(player.mode !== 'play') return;

  // movement
  let v = 0;
  if(keys.left) v -= 1;
  if(keys.right) v += 1;
  player.x = clamp(player.x + v*130*dt, 10, 214);

  // firing (max 2 shots on screen)
  if(keys.fire && player.fireCd <= 0){
    const n = shots.length;
    if(n < 2){
      if(!player.dual){
        shots.push({x: player.x, y: player.y-10});
      } else {
        const lx = player.x - 8, rx = player.x + 8;
        if(n === 0){
          shots.push({x: player.dualSide==='L' ? lx : rx, y: player.y-10});
        } else {
          shots.push({x: player.dualSide==='L' ? rx : lx, y: player.y-10});
        }
      }
      shotsFired++;
      player.fireCd = 0.18;
      SFX.shot();
    }
  }
}
// (dual bookkeeping: dualSide tracks which side the blue ship is on)
player.dualSide = 'L';

// ---------------- freed captives ----------------
function freeCaptive(x, y){
  if(player.mode === 'play' && !player.dual){
    freed.push({ x, y, t:0, dock: true });
  } else {
    freed.push({ x, y, t:0, dock: false });
  }
}
function updateFreed(dt){
  for(const f of freed){
    f.t += dt;
    const targetX = f.dock ? player.x : f.x;
    f.x += (targetX - f.x) * Math.min(1, dt*4);
    f.y += 120*dt;
    if(f.dock && f.y >= player.y - 14){
      // dock beside the player -> dual fighter
      player.dual = true;
      player.dualSide = 'L';           // blue on left, red on right
      SFX.dual();
      addPopup(player.x, player.y-30, 'DUAL FIGHTER', '#ff4444');
      f.done = true;
    }
    if(f.y > H + 20) f.done = true;
  }
  freed = freed.filter(f => !f.done);
}

// ---------------- enemy update ----------------
function updateEnemies(dt){
  const canDive = player.mode === 'play' && !chall && !stageClear;
  const canFire = player.mode === 'play' || player.mode === 'ready';

  // pending entries
  for(let i = entryQ.length-1; i >= 0; i--){
    const q = entryQ[i];
    if(stageTime >= q.t){
      entryQ.splice(i,1);
      enemies.push(makeEnemy(q.slot, q.side, 0, q.dur, {fireAt: q.fireAt}));
    }
  }

  // dive scheduler
  if(canDive){
    diveT -= dt;
    if(diveT <= 0){
      startDive();
      const base = Math.max(0.7, 2.4 - stage*0.15);
      diveT = base * rand(0.7, 1.3);
    }
  }
  // formation / entry fire
  if(canFire && !chall){
    formFireT -= dt;
    if(formFireT <= 0){
      const shooters = enemies.filter(e => (e.st==='formation' || e.st==='entering') && !e.captive);
      if(shooters.length){
        const e = shooters[(Math.random()*shooters.length)|0];
        eFire(e.x, e.y+8, true);
        SFX.enemyHit();
      }
      formFireT = Math.max(0.35, 1.3 - stage*0.09) * rand(0.7,1.3);
    }
  }

  formT += dt;
  const sway = formationFull ? 0 : Math.sin(formT*1.1)*10;
  const breath = formationFull ? 1 + 0.07*Math.sin(formT*1.4) : 1;
  const cx = 112, cy = 100;

  for(const e of enemies){
    // wing-flap animation (2 frames)
    e.animT += dt;
    if(e.animT > 0.35){ e.animT = 0; e.animFrame ^= 1; }

    switch(e.st){
      case 'wait': break;
      case 'entering': {
        e.t += dt;
        const k = clamp(e.t / e.dur, 0, 1);
        const p = bez(e.path, k);
        e.x = p.x; e.y = p.y;
        // may fire while entering
        for(let i=0;i<e.fireAt.length;i++){
          if(!e.fireAt[i].done && e.t >= e.fireAt[i].at){ e.fireAt[i].done = true; eFire(e.x, e.y+8, true); }
        }
        if(k >= 1){ e.st = 'formation'; e.x = e.slot.x; e.y = e.slot.y; }
        break;
      }
      case 'formation': {
        e.x = cx + (e.slot.x - cx)*breath + sway;
        e.y = cy + (e.slot.y - cy)*breath;
        break;
      }
      case 'diving': {
        e.t += dt;
        const k = clamp(e.t / e.dur, 0, 1);
        const p = bez(e.path, k);
        e.x = p.x; e.y = p.y;
        for(let i=0;i<e.fireAt.length;i++){
          if(!e.fireAt[i].done && e.t >= e.fireAt[i].at){ e.fireAt[i].done = true; eFire(e.x, e.y+8, true); }
        }
        if(k >= 1){
          if(e.captive){
            // boss with captive: stop and project the tractor beam
            e.st = 'beam'; e.t = 0;
            beam = { x: e.x, t: 0, boss: e };
            SFX.beam(2.6);
          } else {
            const p2 = returnPath(e);
            e.path = p2.path; e.dur = p2.dur; e.t = 0; e.st = 'returning';
          }
        }
        break;
      }
      case 'beam': {
        e.t += dt;
        beam.x = e.x; beam.t = e.t;
        const w = beamWidth(e.t);
        if(player.mode === 'play' && !player.dual &&
           Math.abs(player.x - e.x) < w/2){
          // captured!
          player.mode = 'captured'; player.t = 0;
          player.capX = player.x; player.capY = player.y;
          player.capTargetY = e.y - 16;
          SFX.capture();
        }
        if(e.t > 2.6){
          // boss returns to slot, still holding the captive
          beam = null;
          const p2 = returnPath(e);
          e.path = p2.path; e.dur = p2.dur; e.t = 0; e.st = 'returning';
        }
        break;
      }
      case 'returning': {
        e.t += dt;
        const k = clamp(e.t / e.dur, 0, 1);
        const p = bez(e.path, k);
        e.x = p.x; e.y = p.y;
        if(k >= 1){ e.st = 'formation'; e.x = e.slot.x; e.y = e.slot.y; }
        break;
      }
    }

    // captive fighter rides above its boss
    if(e.captive){ e.capX = e.x; e.capY = e.y - 16; }
  }

  // captive fires when its boss dives
  for(const e of enemies){
    if(e.captive && (e.st==='diving' || e.st==='beam')){
      e.capFire = (e.capFire || 0) - dt;
      if(e.capFire <= 0 && canFire){
        eFire(e.capX, e.capY+8, true);
        e.capFire = 0.9;
      }
    }
  }

  // entry bookkeeping
  if(!chall){
    const allIn = enemies.length > 0 && enemies.every(e => e.st==='formation' || e.st==='diving' || e.st==='returning' || e.st==='beam');
    if(allIn && entryQ.length === 0) formationFull = true;
  }
}
function beamWidth(t){ return Math.min(46, 10 + t*14); }

// ---------------- challenging stage ----------------
function challX(wave, th){
  return wave.x0 + wave.dir * (5*th - 24*Math.sin(th));
}
function updateChall(dt){
  if(!chall) return;
  for(const wave of chall.waves){
    if(wave.done) continue;
    if(stageTime >= wave.startAt){
      // spawn the 8 enemies of this wave (staggered by j)
      for(const en of wave.enemies){
        if(en.spawned) continue;
        const tStart = wave.startAt + en.j*0.4;
        if(stageTime >= tStart){
          en.spawned = true;
          const e = { type: en.type, st:'chall', wave, j: en.j, dir: wave.dir, x0: wave.x0,
                      hp:1, x: en.x0, y:-24, dead:false, animFrame:0, animT:0 };
          e.th = 0;
          enemies.push(e);
        }
      }
    }
  }
  for(const e of enemies){
    if(e.st !== 'chall') continue;
    e.animT += dt;
    if(e.animT > 0.35){ e.animT = 0; e.animFrame ^= 1; }
    e.th += 3.4*dt;
    e.y = -24 + 7*e.th;
    e.x = challX(e.wave, e.th);
    if(e.y > H + 24){
      e.dead = true;
      if(e.wave.kills + e.wave.escaped === 8) finishWave(e.wave);
    }
  }
  if(!chall.done && chall.waves.every(w => w.done)){
    chall.done = true;
    if(chHits === 40){ addScore(10000); chBonuses.push(10000); SFX.bonus(); }
    resT = 3.2;
    state = 'results';
  }
}
function finishWave(wave){
  if(wave.bonus) return;
  wave.bonus = true; wave.done = true;
  if(wave.kills === 8){ addScore(1000); chBonuses.push(1000); SFX.bonus(); addPopup(112, 140, '1000', '#33ccff'); }
}

// ---------------- shots & collisions ----------------
function updateShots(dt){
  for(const s of shots){ s.y -= 260*dt; if(s.y < 24) s.dead = true; }
  for(const b of ebullets){ b.x += b.vx*dt; b.y += b.vy*dt; if(b.y > H+8 || b.x < -8 || b.x > W+8) b.dead = true; }

  // player shots vs enemies
  for(const s of shots){
    if(s.dead) continue;
    for(const e of enemies){
      if(e.dead || e.st==='wait') continue;
      if(!aabb(s.x-1, s.y-3, 2, 6, e.x-6, e.y-6, 12, 12)) continue;
      s.dead = true; shotsHit++;
      if(e.st === 'chall'){
        e.dead = true; e.wave.kills++;
        addScore(100); addPopup(e.x, e.y, '100', '#fff');
        addBoom(e.x, e.y, BOOM_E); SFX.enemyBoom();
        if(e.wave.kills + e.wave.escaped === 8) finishWave(e.wave);
        break;
      }
      e.hp--;
      if(e.hp > 0){
        if(e.type==='boss'){ SFX.bossHit(); addPopup(e.x, e.y, '150', '#fff'); }
        else { SFX.enemyHit(); }
      } else {
        destroyEnemy(e);
      }
      break;
    }
  }

  // enemy bullets vs player
  if(player.mode === 'play'){
    const boxes = player.dual
      ? [{x:player.x-16, w:16},{x:player.x, w:16}]
      : [{x:player.x-8, w:16}];
    for(const b of ebullets){
      if(b.dead) continue;
      for(const bx of boxes){
        if(aabb(b.x-2, b.y-2, 4, 4, bx.x+4, player.y-6, 8, 12)){
          b.dead = true;
          if(player.dual){
            // only the hit half is lost
            player.dual = false;
            SFX.enemyHit();
            addBoom(b.x, b.y, BOOM_E);
          } else {
            killPlayer();
          }
          break;
        }
      }
    }
    // rams
    for(const e of enemies){
      if(e.dead || e.st==='wait' || e.st==='chall') continue;
      for(const bx of boxes){
        if(aabb(e.x-6, e.y-6, 12, 12, bx.x+4, player.y-6, 8, 12)){
          if(player.dual){
            player.dual = false; e.dead = true;
            addBoom(e.x, e.y, BOOM_E); SFX.enemyBoom();
            addBoom(player.x, player.y, BOOM_P); SFX.playerBoom();
          } else {
            e.dead = true;
            addBoom(e.x, e.y, BOOM_E);
            killPlayer();
          }
          break;
        }
      }
    }
  }

  shots = shots.filter(s => !s.dead);
  ebullets = ebullets.filter(b => !b.dead);
}

function destroyEnemy(e){
  if(e.dead) return;
  e.dead = true;
  if(e.st === 'chall') return; // handled by caller
  let pts;
  if(e.type==='zako')  pts = e.st==='formation' ? 50 : 100;
  else if(e.type==='goye') pts = e.st==='formation' ? 80 : 160;
  else {
    if(e.st === 'formation') pts = 150;
    else pts = 400 + 400*e.esc;   // 400 / 800 / 1600
  }
  addScore(pts);
  addPopup(e.x, e.y, String(pts), e.type==='boss' ? '#33ccff' : '#fff');
  addBoom(e.x, e.y, BOOM_E, e.type==='boss' ? 0.07 : 0.05);
  if(e.type === 'boss'){
    SFX.bossBoom();
    if(e.captive){
      if(e.st === 'diving' || e.st === 'beam'){
        // boss shot while diving: captive is freed -> dual fighter
        freeCaptive(e.capX, e.capY);
        e.captive = false;
      } else {
        // boss shot in formation: captive destroyed with it
        addBoom(e.capX, e.capY, BOOM_P);
        e.captive = false;
      }
    }
    if(beam && beam.boss === e) beam = null;
  } else {
    SFX.enemyBoom();
  }
  enemies = enemies.filter(o => !o.dead);
}

// ---------------- stage progression ----------------
function checkStageEnd(dt){
  if(chall) return; // challenging handled in updateChall
  if(stageClear) return;
  if(enemies.length === 0 && entryQ.length === 0 && stageTime > 2){
    stageClear = true; clearT = 1.6;
  }
  if(stageClear){
    clearT -= dt;
    if(clearT <= 0){
      stage++;
      state = 'intro'; introT = 2.2;
      SFX.jingle();
    }
  }
}

// ---------------- master update ----------------
function update(dt){
  time += dt;
  updateStars(dt);
  if(paused) return;

  switch(state){
    case 'title': break;
    case 'intro':
      introT -= dt;
      if(introT <= 0){ state = 'play'; setupStage(); }
      break;
    case 'play': {
      stageTime += dt;
      updatePlayer(dt);
      if(chall) updateChall(dt);
      else updateEnemies(dt);
      if(chall){
        // still run basic enemy anim for challenging flyers
        for(const e of enemies){
          if(e.st !== 'chall') continue;
        }
      }
      updateShots(dt);
      updateFreed(dt);
      // booms / popups
      for(const b of booms) b.f += dt/ b.step;
      booms = booms.filter(b => b.f < 3);
      for(const p of popups){ p.t += dt; p.y -= 12*dt; }
      popups = popups.filter(p => p.t < 1.1);
      enemies = enemies.filter(e => !e.dead);
      checkStageEnd(dt);
      break;
    }
    case 'results':
      resT -= dt;
      for(const p of popups){ p.t += dt; p.y -= 12*dt; }
      popups = popups.filter(p => p.t < 1.1);
      if(resT <= 0){ stage++; state='intro'; introT=2.2; SFX.jingle(); }
      break;
    case 'over':
      overT -= dt;
      for(const p of popups){ p.t += dt; p.y -= 12*dt; }
      if(overT <= 0){ state = 'title'; }
      break;
  }
}

