    if(e.x < -16 || e.x > W+16 || e.y < -16 || e.y > H+16) continue;
    ctx.drawImage(enemySprite(e), (e.x-8)|0, (e.y-8)|0);
    if(e.captive && e.st !== 'chall'){
      ctx.drawImage(SPR.fighterRed, (e.capX-8)|0, (e.capY-8)|0);
    }
  }
  // freed captives
  for(const f of freed){
    ctx.drawImage(SPR.fighterRed, (f.x-8)|0, (f.y-8)|0);
  }
  drawPlayer();

  // bullets
  for(const s of shots) ctx.drawImage(SPR.pshot, (s.x-1)|0, (s.y-3)|0);
  for(const b of ebullets) ctx.drawImage(SPR.ebullet, (b.x-2)|0, (b.y-2)|0);

  // explosions
  for(const b of booms){
    const f = Math.min(2, b.f|0);
    const spr = b.set[f];
    const sz = spr.width;
    ctx.drawImage(spr, (b.x - sz/2)|0, (b.y - sz/2)|0);
  }
  // score popups
  for(const p of popups){
    drawText(p.txt, p.x, p.y, p.color, 1, true);
  }

  drawHUD();

  // overlays
  if(state === 'intro'){
    drawText('STAGE ' + stage, 112, 120, '#ffffff', 2, true);
  }
  if(state === 'results'){
    drawText('NUMBER OF HITS', 112, 96, '#ffffff', 1, true);
    drawText(String(chHits), 112, 110, '#33ccff', 2, true);
    let y = 136;
    for(const b of chBonuses){
      drawText(b === 10000 ? 'PERFECT! 10000' : 'BONUS ' + b, 112, y, '#ffee00', 1, true);
      y += 12;
    }
  }
  if(state === 'over'){
    drawText('GAME OVER', 112, 84, '#ff2222', 2, true);
    const ratio = shotsFired ? Math.round(100*shotsHit/shotsFired) : 0;
    drawText('SHOTS ' + shotsFired, 112, 128, '#ffffff', 1, true);
    drawText('HITS ' + shotsHit, 112, 142, '#ffffff', 1, true);
    drawText('RATIO ' + ratio + '%', 112, 156, '#33ccff', 1, true);
  }
  if(paused && state === 'play'){
    drawText('PAUSE', 112, 132, '#ffffff', 2, true);
  }
}

// ---------------- input ----------------
const keys = { left:false, right:false, fire:false };
addEventListener('keydown', ev => {
  const k = ev.key;
  if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(k)) ev.preventDefault();
  initAudio();
  if(k === 'ArrowLeft' || k === 'a' || k === 'A') keys.left = true;
  if(k === 'ArrowRight' || k === 'd' || k === 'D') keys.right = true;
  if(k === ' ') keys.fire = true;
  if(k === 'Enter'){
    if(state === 'title'){ startGame(); }
    else if(state === 'over'){ state = 'title'; }
  }
  if(k === 'p' || k === 'P'){ if(state === 'play') paused = !paused; }
  if(k === 'm' || k === 'M'){ muted = !muted; }
});
addEventListener('keyup', ev => {
  const k = ev.key;
  if(k === 'ArrowLeft' || k === 'a' || k === 'A') keys.left = false;
  if(k === 'ArrowRight' || k === 'd' || k === 'D') keys.right = false;
  if(k === ' ') keys.fire = false;
});
function startGame(){
  score = 0; stage = 1; reserve = 2; nextExtra = 20000;
  shotsFired = 0; shotsHit = 0;
  player.x = 112; player.mode = 'ready'; player.t = 0; player.dual = false;
  respawnT = 0; overT = 0;
  state = 'intro'; introT = 2.2;
  SFX.jingle();
}

// ---------------- fixed-timestep main loop ----------------
let last = performance.now(), acc = 0;
function frame(now){
  requestAnimationFrame(frame);
  let dt = (now - last) / 1000;
  last = now;
  if(dt > 0.25) dt = 0.25;
  acc += dt;
  while(acc >= STEP){ update(STEP); acc -= STEP; }
  render();
}
requestAnimationFrame(frame);
</script>
